package local.ondemand;
import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
/** A compact horizontal movie shelf below sources, with captured parent state for Back. */
final class MoreLikeThis {
 final MainActivity a;final SourcePicker owner;final JSONObject original;final long loadedAt;final LinearLayout section,row;final HorizontalScrollView scroll;final TextView note;final List<View> cards=new ArrayList<>();int token;boolean loaded,loading;View returnSource,lastCard;
 MoreLikeThis(MainActivity app,SourcePicker picker){a=app;owner=picker;original=a.selected==null?new JSONObject():a.selected;loadedAt=a.sourceLoadedAt;section=new LinearLayout(a);section.setTag("similar:section");section.setOrientation(1);section.setPadding(0,a.dp(7),0,a.dp(5));TextView heading=a.text("More like this",16);heading.setPadding(a.dp(3),0,0,a.dp(3));section.addView(heading,new LinearLayout.LayoutParams(-1,a.dp(25)));note=a.text("Finding related movies…",11);note.setTag("similar:status");note.setTextColor(0xffa8b4c5);note.setPadding(a.dp(3),0,0,a.dp(3));section.addView(note);scroll=new HorizontalScrollView(a);scroll.setTag("similar:scroll");scroll.setHorizontalScrollBarEnabled(false);scroll.setFocusable(false);scroll.setClipToPadding(false);scroll.setSmoothScrollingEnabled(true);row=new LinearLayout(a);row.setClipChildren(false);row.setPadding(a.dp(3),a.dp(4),a.dp(3),a.dp(4));scroll.addView(row);section.addView(scroll,new LinearLayout.LayoutParams(-1,a.dp(40)));a.rows.addView(section,new LinearLayout.LayoutParams(-1,-2));resume();}
 boolean active(){return token==a.generation&&a.picker==owner&&a.rows!=null&&a.rows.findViewWithTag("similar:section")==section&&!a.isFinishing();}
 void resume(){if(loaded)return;if(loading&&token==a.generation)return;loading=false;token=a.generation;List<JSONObject> cached=a.similarCache.get(owner.id);if(cached!=null){loaded=true;render(cached);return;}load();}
 void load(){if(!active()||loading)return;loading=true;note.setVisibility(View.VISIBLE);note.setText("Finding related movies…");final int generation=token;final Api api=a.api;a.relatedWorker.submit(()->{List<JSONObject> found=null;try{found=SimilarMovies.find(api,original,()->generation==a.generation&&!a.isDestroyed());}catch(Exception ignored){}final List<JSONObject> matches=found;a.clock.post(()->{if(!active()||generation!=token)return;loading=false;if(matches==null){note.setVisibility(View.VISIBLE);note.setText("Related movies unavailable · select to retry");scroll.getLayoutParams().height=a.dp(40);scroll.setVisibility(View.VISIBLE);Button retry=a.button("Retry related movies",this::load);retry.setTag("similar:retry");retry.setTextSize(12);retry.setOnKeyListener((v,k,e)->{if(k!=19)return false;if(e.getAction()==0)backToSources();return true;});row.removeAllViews();row.addView(retry,new LinearLayout.LayoutParams(a.dp(160),a.dp(32)));return;}loaded=true;a.similarCache.put(owner.id,new ArrayList<>(matches));render(matches);});});}
 void render(List<JSONObject> movies){scroll.getLayoutParams().height=a.dp(142);scroll.setVisibility(movies.isEmpty()?View.GONE:View.VISIBLE);row.removeAllViews();cards.clear();note.setText(movies.isEmpty()?"No close matches found":"");note.setVisibility(movies.isEmpty()?View.VISIBLE:View.GONE);for(JSONObject movie:movies){View card=PosterCard.create(a,movie,"similar:movie:"+movie.optString("id"),()->open(movie));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(a.dp(76),a.dp(134));p.rightMargin=a.dp(8);row.addView(card,p);cards.add(card);}if(cards.isEmpty())row.getLayoutParams().height=a.dp(8);for(int i=0;i<cards.size();i++){final int at=i;cards.get(i).setOnKeyListener((v,k,e)->{if(k!=19&&k!=20&&k!=21&&k!=22)return false;if(e.getAction()==0){lastCard=v;if(k==19)backToSources();else if(k==21)cards.get(Math.max(0,at-1)).requestFocus();else if(k==22)cards.get(Math.min(cards.size()-1,at+1)).requestFocus();}return true;});}if(a.restoreFocus.startsWith("similar:movie:")){View restored=row.findViewWithTag(a.restoreFocus);if(restored!=null){lastCard=restored;final String wanted=a.restoreFocus;a.clock.post(()->{if(active()&&wanted.equals(a.restoreFocus)){restored.requestFocus();a.restoreFocus="";}});}}}
 void enter(View from){returnSource=from;View first=lastCard!=null&&lastCard.getParent()!=null?lastCard:!cards.isEmpty()?cards.get(0):row.findViewWithTag("similar:retry");if(first!=null)first.requestFocus();}
 void backToSources(){View target=returnSource!=null&&returnSource.isAttachedToWindow()?returnSource:a.rows.findViewWithTag("selection:trailer");if(target==null||target.getVisibility()!=View.VISIBLE)target=a.rows.findViewWithTag("selection:artwork");if(target!=null)target.requestFocus();}
 boolean inside(ViewGroup parent,View v){while(v!=null){if(v==parent)return true;android.view.ViewParent p=v.getParent();v=p instanceof View?(View)p:null;}return false;}
 void wire(LinearLayout rail,View primary){returnSource=primary;List<View> buttons=new ArrayList<>();owner.collect(rail,buttons);for(View b:buttons)b.setOnKeyListener((v,k,e)->{int direction=k==19?View.FOCUS_UP:k==20?View.FOCUS_DOWN:k==21?View.FOCUS_LEFT:k==22?View.FOCUS_RIGHT:0;if(direction==0)return false;if(e.getAction()==0){if(k==21){View art=a.rows.findViewWithTag("selection:artwork");if(art!=null)art.requestFocus();}else{View next=v.focusSearch(direction);if(next!=null&&inside(rail,next))next.requestFocus();else if(k==20)enter(v);}}return true;});}
 void open(JSONObject movie){View chosen=row.findViewWithTag("similar:movie:"+movie.optString("id"));if(chosen!=null)chosen.requestFocus();a.current=()->{a.selected=original;a.type=owner.type;a.videoId=owner.id;a.videoName=owner.name;a.sourceItems=owner.all;a.sourceKey=owner.type+":"+owner.id;a.sourceLoadedAt=loadedAt;a.sourceList();};a.go(()->{a.selected=movie;a.type="movie";a.detail();});}
}
